tool_input_args.value:
cd /workspace && node -e "
const XLSX = require('xlsx');
const wb = XLSX.readFile('testbed/data/travel_expenses.xlsx');
wb.SheetNames.forEach(name => {
  console.log('=== Sheet:', name, '===');
  const data = XLSX.utils.sheet_to_json(wb.Sheets[name], {header:1});
  data.forEach(row => console.log(JSON.stringify(row)));
});
"

cd /workspace && node -e "
const XLSX = require('xlsx');
const wb = XLSX.readFile('testbed/data/budget.xlsx');
wb.SheetNames.forEach(name => {
  console.log('=== Sheet:', name, '===');
  const data = XLSX.utils.sheet_to_json(wb.Sheets[name], {header:1});
  data.forEach(row => console.log(JSON.stringify(row)));
});
"

cd /workspace && node -e "
const db = require('better-sqlite3')('world.db');
const tables = db.prepare(\"SELECT name FROM sqlite_master WHERE type='table'\").all();
console.log('Tables:', tables.map(t => t.name));
tables.forEach(t => {
  const cols = db.prepare('PRAGMA table_info(' + t.name + ')').all();
  console.log('\n' + t.name + ':', cols.map(c => c.name).join(', '));
  const rows = db.prepare('SELECT * FROM ' + t.name + ' LIMIT 2').all();
  rows.forEach(r => console.log(JSON.stringify(r)));
});
"

