tool_input_args.value:
cd /workspace && node -e "
const db = require('better-sqlite3')('world.db');
// Look for any expense-like table or EX001-related data
const tables = db.prepare(\"SELECT name FROM sqlite_master WHERE type='table'\").all();
tables.forEach(t => {
  try {
    const count = db.prepare('SELECT COUNT(*) as c FROM ' + t.name).get();
    if (count.c > 0) {
      // Search for EX001, boston, BostonTech
      const rows = db.prepare('SELECT * FROM ' + t.name).all();
      rows.forEach(r => {
        const s = JSON.stringify(r);
        if (/EX001|boston|BostonTech/i.test(s)) {
          console.log(t.name + ':', s);
        }
      });
    }
  } catch(e) {}
});
"

