cd /workspace && node -e "
const db = require('better-sqlite3')('world.db');
// Find all flights with BOS as origin or destination
const flights = db.prepare(\"SELECT * FROM flights WHERE (origin='BOS' OR destination='BOS') AND source_skill='tau2Airline'\").all();
console.log('Flights involving BOS (tau2Airline):');
flights.forEach(f => {
  console.log(f.flight_id, f.origin, '->', f.destination, 'dep:', f.departure_time, 'arr:', f.arrival_time);
  console.log('  dates:', f.dates_json.substring(0, 300));
});
console.log('Total:', flights.length);
"

cd /workspace && node -e "
const db = require('better-sqlite3')('world.db');
// Find all flights with BOS from any source_skill
const flights = db.prepare(\"SELECT * FROM flights WHERE origin='BOS' OR destination='BOS'\").all();
console.log('All flights involving BOS:');
flights.forEach(f => {
  console.log(f.flight_id, f.source_skill, f.origin, '->', f.destination, 'dep:', f.departure_time, 'arr:', f.arrival_time);
  console.log('  prices:', f.cabin_prices_json);
  console.log('  dates:', f.dates_json.substring(0, 500));
  console.log();
});
console.log('Total:', flights.length);
"

cd /workspace && node -e "
const db = require('better-sqlite3')('world.db');
// Get all unique origins and destinations for tau2Airline
const origins = db.prepare(\"SELECT DISTINCT origin FROM flights WHERE source_skill='tau2Airline'\").all();
const dests = db.prepare(\"SELECT DISTINCT destination FROM flights WHERE source_skill='tau2Airline'\").all();
console.log('Origins:', origins.map(r => r.origin));
console.log('Destinations:', dests.map(r => r.destination));

// Also check state-travel flights
const origins2 = db.prepare(\"SELECT DISTINCT origin FROM flights WHERE source_skill='state-travel'\").all();
const dests2 = db.prepare(\"SELECT DISTINCT destination FROM flights WHERE source_skill='state-travel'\").all();
console.log('state-travel Origins:', origins2.map(r => r.origin));
console.log('state-travel Destinations:', dests2.map(r => r.destination));

// All sources
const sources = db.prepare(\"SELECT DISTINCT source_skill FROM flights\").all();
console.log('All source skills:', sources.map(r => r.source_skill));

// All unique cities
const all = db.prepare(\"SELECT DISTINCT origin FROM flights UNION SELECT DISTINCT destination FROM flights\").all();
console.log('All airports:', all.map(r => r.origin));
"

cd /workspace && node -e "
const db = require('better-sqlite3')('world.db');
// Check for any mention of 'EX001' in any table
const tables = db.prepare(\"SELECT name FROM sqlite_master WHERE type='table'\").all();
tables.forEach(t => {
  try {
    const rows = db.prepare('SELECT * FROM ' + t.name).all();
    rows.forEach(r => {
      const s = JSON.stringify(r);
      if (/EX001/i.test(s)) {
        console.log(t.name + ':', s.substring(0, 300));
      }
    });
  } catch(e) {}
});
// Also check the budget xlsx
console.log('\\nBudget: Travel = \$1,200');
"

cd /workspace && node -e "
const db = require('better-sqlite3')('world.db');

// First, find all tau2Airline flights from SFO
const fromSFO = db.prepare(\"SELECT * FROM flights WHERE origin='SFO' AND source_skill='tau2Airline'\").all();
console.log('=== Flights FROM SFO (tau2Airline) ===');
fromSFO.forEach(f => {
  console.log(f.flight_id, f.origin, '->', f.destination, 'dep:', f.departure_time, 'arr:', f.arrival_time);
  const dates = JSON.parse(f.dates_json);
  Object.keys(dates).sort().forEach(d => {
    console.log('  ', d, ':', JSON.stringify(dates[d]));
  });
});

// Find all tau2Airline flights TO JFK
const toJFK = db.prepare(\"SELECT * FROM flights WHERE destination='JFK' AND source_skill='tau2Airline'\").all();
console.log('\n=== Flights TO JFK (tau2Airline) ===');
toJFK.forEach(f => {
  console.log(f.flight_id, f.origin, '->', f.destination, 'dep:', f.departure_time, 'arr:', f.arrival_time);
  const dates = JSON.parse(f.dates_json);
  Object.keys(dates).sort().forEach(d => {
    console.log('  ', d, ':', JSON.stringify(dates[d]));
  });
});
"

