cd /workspace && node -e "
const db = require('better-sqlite3')('world.db');

// Check ALL flights in tau2Airline that go to JFK from any origin
const toJFK = db.prepare(\"SELECT * FROM flights WHERE destination='JFK' AND source_skill='tau2Airline'\").all();
console.log('Flights TO JFK (tau2Airline):', toJFK.length);

// Check connecting flights: SFO -> X -> JFK
// First get all SFO destinations
const fromSFO = db.prepare(\"SELECT DISTINCT destination FROM flights WHERE origin='SFO' AND source_skill='tau2Airline'\").all();
console.log('SFO connects to:', fromSFO.map(r => r.destination));

// For each SFO destination, check if there's a flight to JFK
fromSFO.forEach(d => {
  const connecting = db.prepare(\"SELECT * FROM flights WHERE origin=? AND destination='JFK' AND source_skill='tau2Airline'\").all(d.destination);
  console.log(d.destination, '-> JFK:', connecting.length, 'flights');
  connecting.forEach(f => {
    console.log('  ', f.flight_id, f.departure_time, f.arrival_time);
    const dates = JSON.parse(f.dates_json);
    Object.keys(dates).sort().forEach(dt => console.log('    ', dt, JSON.stringify(dates[dt])));
  });
});

// Also check if there are ANY flights to JFK from ANY airport
const anyToJFK = db.prepare(\"SELECT * FROM flights WHERE destination='JFK'\").all();
console.log('\nAll flights to JFK (any skill):');
anyToJFK.forEach(f => {
  console.log(f.flight_id, f.source_skill, f.origin, '->', f.destination, 'dep:', f.departure_time, 'arr:', f.arrival_time);
  const dates = JSON.parse(f.dates_json);
  Object.keys(dates).sort().forEach(dt => console.log('  ', dt, JSON.stringify(dates[dt]).substring(0, 200)));
});
"

cd /workspace && node -e "
const db = require('better-sqlite3')('world.db');

// Let's check ALL tau2Airline flights and their routes
const all = db.prepare(\"SELECT flight_id, origin, destination, departure_time, arrival_time, dates_json FROM flights WHERE source_skill='tau2Airline'\").all();
console.log('ALL tau2Airline flights (' + all.length + '):');
all.forEach(f => {
  const dates = JSON.parse(f.dates_json);
  const dateKeys = Object.keys(dates).sort();
  console.log(f.flight_id, f.origin, '->', f.destination, 'dep:', f.departure_time, 'arr:', f.arrival_time, 'dates:', dateKeys.join(', '));
});

// Unique routes
const routes = db.prepare(\"SELECT DISTINCT origin, destination FROM flights WHERE source_skill='tau2Airline'\").all();
console.log('\nUnique routes:');
routes.forEach(r => console.log(r.origin, '->', r.destination));
"

cd /workspace && node -e "
// The transfer_to_human_agents tool simply returns 'Transfer successful'
// and logs the summary. We'll record the transfer action in world_meta for traceability.

const Database = require('better-sqlite3');
const db = new Database('world.db');

const summary = 'User needs to book a one-stop flight from SFO to Boston (BOS) or JFK for the BostonTech conference, arriving by July 3, 2026. The trip is associated with approved travel expense EX001, with a travel budget of \$1,200. The tau2Airline system has no routes to BOS or JFK and no flights available on July 2026 dates. The user is open to flying into JFK and taking ground transport to Boston. A human agent is needed to book through alternative channels.';

// Record the transfer
db.prepare('INSERT OR REPLACE INTO world_meta (key, value) VALUES (?, ?)').run(
  'human_agent_transfer',
  JSON.stringify({
    timestamp: '2026-09-08T10:00:00',
    summary: summary,
    status: 'Transfer successful'
  })
);

console.log('Transfer successful');
console.log();
console.log('Summary provided to human agent:');
console.log(summary);
"
